{"implementation": "def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    edges = []
    for u, v, d in distances:
        if u > v:
            u, v = v, u
        w = max(core_distance[u], core_distance[v], d)
        edges.append((u, v, w))

    edges.sort(key=lambda x: (x[2], x[0], x[1]))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    selected = []
    total = 0.0
    for u, v, w in edges:
        if union(u, v):
            selected.append([u, v, w])
            total += w
            if len(selected) == len(nodes) - 1:
                break

    if len(selected) != len(nodes) - 1:
        raise ValueError("Disconnected graph")

    return {"edges": selected, "total_weight": total}"}
